jmodels = jdata.get('models', {})
ymodels = ydata.get('models', {})

def to_canonical(obj):
    """Convert to a canonical hashable form for comparison."""
    if isinstance(obj, dict):
        return tuple(sorted((k, to_canonical(v)) for k, v in obj.items()))
    elif isinstance(obj, list):
        return tuple(sorted(to_canonical(v) for v in obj, key=str))
    elif isinstance(obj, float):
        # Handle float precision
        return round(obj, 10)
    return obj

total_any_diff = 0
