    jm = jmodels[m]
    ym = ymodels.get(m)
    if ym is None:
        print(f"{m}: MISSING IN YAML")
        total_any_diff += 1
        continue

    jc = to_canonical(jm)
    yc = to_canonical(ym)
    if jc != yc:
        total_any_diff += 1

        jkeys = set(jm.keys())
        ykeys = set(ym.keys())

        only_j = jkeys - ykeys
        only_y = ykeys - jkeys
        common_k = jkeys & ykeys

        if only_j:
            print(f"\n{m} — Only in JSON: {sorted(only_j)}")
        if only_y:
            print(f"\n{m} — Only in YAML: {sorted(only_y)}")

        for k in sorted(common_k):
            if to_canonical(jm[k]) != to_canonical(ym[k]):
                print(f"\n{m} — DIFF in '{k}':")
                print(f"  JSON: {json.dumps(jm[k], default=str, indent=2)}")
                print(f"  YAML: {json.dumps(ym[k], default=str, indent=2)}")

if total_any_diff == 0:
    print("ALL 82 MODELS ARE IDENTICAL between JSON and YAML")
else:
    print(f"\n\nTotal models with any diff: {total_any_diff}")
